--- a/training/level-2/L2-005-contact-store/contactStore.mjs
+++ b/training/level-2/L2-005-contact-store/contactStore.mjs
@@ -0,0 +1,74 @@
+// contactStore.mjs
+
+import { promises as fs } from 'fs';
+import { dirname } from 'path';
+import { randomUUID } from 'crypto';
+
+const DB_FILE = 'contacts.json';
+
+async function loadContacts() {
+  try {
+    const data = await fs.readFile(DB_FILE, 'utf-8');
+    const contacts = JSON.parse(data);
+    return contacts;
+  } catch (err) {
+    if (err.code === 'ENOENT') {
+      return [];
+    }
+    throw err;
+  }
+}
+
+async function saveContacts(contacts) {
+  const tempFile = `${DB_FILE}.tmp_${randomUUID()}`;
+  await fs.writeFile(tempFile, JSON.stringify(contacts, null, 2));
+  await fs.rename(tempFile, DB_FILE);
+}
+
+export default {
+  async getContacts() {
+    return await loadContacts();
+  },
+
+  async addContact(contact) {
+    const contacts = await loadContacts();
+    if (contacts.some(c => c.id === contact.id)) {
+      throw new Error('STATE_CORRUPT');
+    }
+    contacts.push(contact);
+    await saveContacts(contacts);
+  },
+
+  async updateContact(id, updates) {
+    const contacts = await loadContacts();
+    const contact = contacts.find(c => c.id === id);
+    if (!contact) {
+      throw new Error('STATE_CORRUPT');
+    }
+    Object.assign(contact, updates);
+    await saveContacts(contacts);
+  },
+
+  async deleteContact(id) {
+    const contacts = await loadContacts();
+    const contactIndex = contacts.findIndex(c => c.id === id);
+    if (contactIndex === -1) {
+      throw new Error('STATE_CORRUPT');
+    }
+    contacts.splice(contactIndex, 1);
+    await saveContacts(contacts);
+  },
+
+  async getContact(id) {
+    const contacts = await loadContacts();
+    const contact = contacts.find(c => c.id === id);
+    if (!contact) {
+      return [];
+    }
+    return [deepClone(contact)];
+  },
+
+  deepClone(obj) {
+    return JSON.parse(JSON.stringify(obj));
+  }
+};

